.builder-grid{display:grid;grid-template-columns:1.3fr .7fr;gap:16px}.builder-card{background:rgba(255,255,255,.025);border:1px solid var(--line);border-radius:18px;padding:18px}.full-card{margin-top:16px}.card-head{display:flex;justify-content:space-between;margin-bottom:14px;color:#d9edf2}.card-head span{font-size:10px;color:#6e8d9a}.menu-row{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid rgba(104,204,235,.08);background:rgba(255,255,255,.018);border-radius:11px;margin-bottom:7px;flex-wrap:wrap}.children{display:flex;flex-direction:column;width:calc(100% - 15px);margin-left:15px}.drag{cursor:grab;color:#56d2ee}.menu-main{flex:1;min-width:120px}.menu-main strong{display:block;color:#dceff3;font-size:12px}.menu-main small{display:block;color:#6e8d9a;font-size:9px;margin-top:3px}.menu-row a{color:#56d2ee;text-decoration:none;font-size:10px}.builder-form,.edit-grid{display:grid;gap:10px}.builder-form label,.edit-box label{font-size:10px;color:#88a6b1}.builder-form input,.builder-form select,.edit-box input,.edit-box select{width:100%;box-sizing:border-box;margin-top:5px;padding:10px;border-radius:9px;border:1px solid var(--line);background:#071b27;color:#e8f6fa}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto!important;margin:0!important}.primary,.edit-title button{border:0;border-radius:9px;padding:10px 13px;background:#31afd2;color:#fff;font-weight:700;cursor:pointer}.edit-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.edit-box{padding:13px;border:1px solid var(--line);border-radius:12px}.edit-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;color:#dceff3}.edit-title button{padding:7px 10px;font-size:10px}.notice{padding:12px;border-radius:11px;margin-bottom:14px;background:rgba(67,194,137,.1);color:#a8e5ca}.empty{text-align:center;color:#708d99;padding:28px}@media(max-width:800px){.builder-grid,.edit-grid{grid-template-columns:1fr}}
