@push('scripts')<script>document.getElementById('page-link')?.addEventListener('change',e=>{document.getElementById('item-url').value=e.target.value});const tree=document.getElementById('menu-tree');let dragged=null;tree?.querySelectorAll(':scope>.menu-row').forEach(row=>{row.addEventListener('dragstart',()=>dragged=row);row.addEventListener('dragover',e=>{e.preventDefault();if(dragged&&dragged!==row)tree.insertBefore(dragged,row)});row.addEventListener('dragend',async()=>{const ids=[...tree.querySelectorAll(':scope>.menu-row')].map(x=>x.dataset.id);await fetch('{{route('admin.navigation.reorder')}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}','Accept':'application/json'},body:JSON.stringify({menu:'{{$menu}}',ids})});});});</script>@endpush
